def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def is_err(v: int | str) -> bool:
        return isinstance(v, str)

    def trunc_div(a: int, b: int) -> int | str:
        if b == 0:
            return "#DIV/0!"
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    def eval_cell(name: str) -> int | str:
        if name not in cells:
            return 0
        if name in memo:
            return memo[name]
        if name in visiting:
            return "#CYCLE!"
        visiting.add(name)
        raw = cells[name].strip()
        if raw.startswith("="):
            val = eval_ast(Parser(raw[1:]).parse_expr())
        else:
            val = int(raw)
        visiting.remove(name)
        memo[name] = val
        return val

    def eval_ast(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return eval_cell(node[1])
        if kind == "neg":
            v = eval_ast(node[1])
            return v if is_err(v) else -v
        if kind == "bin":
            op, left, right = node[1], node[2], node[3]
            l = eval_ast(left)
            if is_err(l):
                return l
            r = eval_ast(right)
            if is_err(r):
                return r
            if op == "+":
                return l + r
            if op == "-":
                return l - r
            if op == "*":
                return l * r
            return trunc_div(l, r)
        if kind == "if":
            l = eval_ast(node[1])
            if is_err(l):
                return l
            r = eval_ast(node[2])
            if is_err(r):
                return r
            op = node[3]
            if op == "=":
                cond = l == r
            elif op == "<>":
                cond = l != r
            elif op == "<":
                cond = l < r
            elif op == "<=":
                cond = l <= r
            elif op == ">":
                cond = l > r
            else:
                cond = l >= r
            return eval_ast(node[4] if cond else node[5])
        return eval_agg(kind, node[1])

    def eval_agg(kind: str, args) -> int | str:
        best: int | None = None
        total = 0
        for arg in args:
            if arg[0] == "range":
                c1, r1, c2, r2 = arg[1], arg[2], arg[3], arg[4]
                clo, chi = (c1, c2) if c1 <= c2 else (c2, c1)
                rlo, rhi = (r1, r2) if r1 <= r2 else (r2, r1)
                for row in range(rlo, rhi + 1):
                    for col in range(ord(clo), ord(chi) + 1):
                        name = chr(col) + str(row)
                        if name not in cells:
                            continue
                        v = eval_cell(name)
                        if is_err(v):
                            return v
                        if kind == "sum":
                            total += v
                        elif best is None or (kind == "min" and v < best) or (kind == "max" and v > best):
                            best = v
            else:
                v = eval_ast(arg)
                if is_err(v):
                    return v
                if kind == "sum":
                    total += v
                elif best is None or (kind == "min" and v < best) or (kind == "max" and v > best):
                    best = v
        if kind == "sum":
            return total
        return 0 if best is None else best

    return {name: eval_cell(name) for name in cells}


class Parser:
    def __init__(self, s: str):
        self.s = s
        self.i = 0
        self.n = len(s)

    def skip(self) -> None:
        while self.i < self.n and self.s[self.i] == " ":
            self.i += 1

    def peek(self) -> str:
        self.skip()
        return self.s[self.i] if self.i < self.n else ""

    def read_digits(self) -> int:
        start = self.i
        while self.i < self.n and self.s[self.i].isdigit():
            self.i += 1
        return int(self.s[start:self.i])

    def parse_expr(self):
        left = self.parse_term()
        while self.peek() in "+-":
            op = self.s[self.i]
            self.i += 1
            right = self.parse_term()
            left = ("bin", op, left, right)
        return left

    def parse_term(self):
        left = self.parse_unary()
        while self.peek() in "*/":
            op = self.s[self.i]
            self.i += 1
            right = self.parse_unary()
            left = ("bin", op, left, right)
        return left

    def parse_unary(self):
        if self.peek() == "-":
            self.i += 1
            return ("neg", self.parse_unary())
        return self.parse_atom()

    def parse_atom(self):
        self.skip()
        ch = self.s[self.i]
        if ch == "(":
            self.i += 1
            e = self.parse_expr()
            self.skip()
            self.i += 1
            return e
        if ch.isdigit():
            return ("num", self.read_digits())
        if self.i + 1 < self.n and self.s[self.i + 1].isalpha():
            start = self.i
            while self.i < self.n and self.s[self.i].isalpha():
                self.i += 1
            return self.parse_call(self.s[start:self.i])
        col = self.s[self.i]
        self.i += 1
        return ("ref", col + str(self.read_digits()))

    def parse_call(self, name: str):
        self.skip()
        self.i += 1
        if name == "IF":
            left = self.parse_expr()
            op = self.parse_cmp()
            right = self.parse_expr()
            self.skip()
            self.i += 1
            then = self.parse_expr()
            self.skip()
            self.i += 1
            else_ = self.parse_expr()
            self.skip()
            self.i += 1
            return ("if", left, right, op, then, else_)
        args = [self.parse_agg_arg()]
        while self.peek() == ",":
            self.i += 1
            args.append(self.parse_agg_arg())
        self.skip()
        self.i += 1
        return (name.lower(), args)

    def parse_cmp(self) -> str:
        self.skip()
        two = self.s[self.i:self.i + 2]
        if two in ("<>", "<=", ">="):
            self.i += 2
            return two
        op = self.s[self.i]
        self.i += 1
        return op

    def parse_agg_arg(self):
        self.skip()
        i = self.i
        s = self.s
        n = self.n
        if i < n and s[i].isalpha() and not (i + 1 < n and s[i + 1].isalpha()):
            j = i + 1
            if j < n and s[j].isdigit():
                while j < n and s[j].isdigit():
                    j += 1
                k = j
                while k < n and s[k] == " ":
                    k += 1
                if k < n and s[k] == ":":
                    c1 = s[i]
                    r1 = int(s[i + 1:j])
                    self.i = k + 1
                    self.skip()
                    c2 = self.s[self.i]
                    self.i += 1
                    r2 = self.read_digits()
                    return ("range", c1, r1, c2, r2)
        return self.parse_expr()
